const adminGetInflight=new Map(),adminGetCache=new Map();
function adminApiBase(){const configured=String(globalThis.SOOP_ADMIN_API_BASE||localStorage.getItem('cnine_admin_api_base')||'').trim();return configured?configured.replace(/\/?$/,'/'):'../api/'}
async function api(path,opt={}){
  const method=String(opt.method||'GET').toUpperCase(),cacheable=method==='GET'&&opt.cacheBust!==true,cacheKey=`${path}|${token}`;
  const now=Date.now(),cached=adminGetCache.get(cacheKey);
  if(cacheable&&cached&&cached.expiresAt>now)return cached.value;
  if(cacheable&&adminGetInflight.has(cacheKey))return adminGetInflight.get(cacheKey);
  const run=(async()=>{
    const controller=new AbortController();
    const timeoutMs=Math.max(5000,Number(opt.timeoutMs||20000));
    const timer=setTimeout(()=>controller.abort(),timeoutMs);
    const externalSignal=opt.signal;
    if(externalSignal){if(externalSignal.aborted)controller.abort();else externalSignal.addEventListener('abort',()=>controller.abort(),{once:true})}
    const requestOpt={...opt};delete requestOpt.timeoutMs;delete requestOpt.signal;delete requestOpt.cacheTtlMs;delete requestOpt.cacheBust;
    try{
      const r=await fetch(adminApiBase()+path,{...requestOpt,signal:controller.signal,headers:{'content-type':'application/json','authorization':'Bearer '+token,...(requestOpt.headers||{})},cache:'no-store'});
      const text=await r.text();let d={};
      try{d=text?JSON.parse(text):{}}catch{const e=Error('API 경로 또는 Cloudflare Functions 연결을 확인해주세요.');e.status=r.status;throw e}
      if(!r.ok){const e=Error(d.error||'요청 실패');e.status=r.status;e.code=d.code;throw e}
      if(cacheable)adminGetCache.set(cacheKey,{value:d,expiresAt:Date.now()+Math.max(3000,Math.min(30000,Number(opt.cacheTtlMs||12000)))});
      else adminGetCache.clear();
      return d;
    }catch(error){
      if(error?.name==='AbortError'){const e=Error('요청 시간이 초과되었습니다. 관리자 로그인은 유지됩니다. 잠시 후 다시 시도해주세요.');e.code='REQUEST_TIMEOUT';throw e}
      throw error;
    }finally{clearTimeout(timer)}
  })();
  if(cacheable)adminGetInflight.set(cacheKey,run);
  try{return await run}finally{if(cacheable)adminGetInflight.delete(cacheKey)}
}

function setBusy(btn,busy,text='처리 중...'){if(!btn)return;btn.disabled=busy;if(!btn.dataset.label)btn.dataset.label=btn.textContent;btn.textContent=busy?text:btn.dataset.label}
async function login(){const btn=$('#loginBtn'),key=$('#key').value.trim();if(!key)return alert('관리자 개인키를 입력하세요.');window.__SOOP_CMS_LOGIN_ACTIVE__=true;setBusy(btn,true,'로그인 확인 중...');try{const d=await api('admin/auth/login',{method:'POST',body:JSON.stringify({privateKey:key})}),role=String(d.user?.role||'').toUpperCase();if(!['OWNER','ADMIN','CARD_MANAGER','EVENT_MANAGER','SUPPORT'].includes(role))throw Error('관리자 권한이 없는 계정입니다.');if(!d.token)throw Error('관리자 로그인 정보를 발급받지 못했습니다.');token=d.token;localStorage.setItem('cnine_admin_token',token);sessionStorage.setItem('cnine_admin_token',token);$('#key').value='';await boot()}catch(e){alert(e.message||'관리자 로그인 중 오류가 발생했습니다.')}finally{window.__SOOP_CMS_LOGIN_ACTIVE__=false;setBusy(btn,false)}}
function setAuthScreen(isAuthenticated){document.body.classList.toggle('auth-active',isAuthenticated);document.body.classList.toggle('auth-guest',!isAuthenticated);$('#login').hidden=isAuthenticated;$('#cms').hidden=!isAuthenticated}
let cmsBootInFlight=false;
async function boot(){
  if(cmsBootInFlight)return;
  cmsBootInFlight=true;
  window.__SOOP_CMS_BOOTING__=true;
  window.__SOOP_CMS_BOOT_ALERTS__.length=0;
  if(token){
    setAuthScreen(false);
    const loginNotice=$('#login .muted');
    if(loginNotice)loginNotice.textContent='저장된 관리자 세션과 CMS 서버 연결을 확인하는 중입니다.';
  }
  try{
    const d=await api('admin/dashboard',{timeoutMs:8000,cacheBust:true});
    state.role=d.role;
    state.admin=d.admin||{nickname:'관리자',role:d.role};
    window.__SOOP_CMS_ACTIVATE_OBSERVERS__?.();
    setAuthScreen(true);
    renderIdentity();
    show('dashboard',d);
  }catch(e){
    if(e.status===401){
      token='';
      localStorage.removeItem('cnine_admin_token');
      sessionStorage.removeItem('cnine_admin_token');
      adminGetCache.clear();
      adminGetInflight.clear();
      setAuthScreen(false);
      const notice=$('#login .muted');
      if(notice)notice.textContent='관리자 세션이 만료되었습니다. 개인키로 다시 로그인해주세요.';
      setTimeout(()=>$('#key')?.focus(),0);
    }else{
      // 네트워크 지연, Cloudflare 오류, 권한별 403은 세션 만료가 아니다.
      // 전체 CMS 모듈을 먼저 노출하면 초기화 요청이 겹칠 수 있으므로 가벼운 재연결 화면을 유지한다.
      setAuthScreen(false);
      const loginNotice=$('#login .muted');
      if(loginNotice)loginNotice.innerHTML=`CMS 연결이 지연되고 있습니다. 저장된 세션은 유지됩니다.<br><small>${esc(e.message)}</small><br><button type="button" id="cmsLoginRetry" style="margin-top:10px">다시 연결</button>`;
      $('#cmsLoginRetry')?.addEventListener('click',boot,{once:true});
    }
  }finally{
    window.__SOOP_CMS_BOOTING__=false;
    cmsBootInFlight=false;
  }
}
// V1802: 와이고수 → PLAY DK 2차 인증 전환 패널. SQL 콘솔 없이 CMS 에서 처리한다.
function wagoMigrationCsv(rows){
  const head=['유저ID','게임닉네임','와이고수닉네임','와이고수회원번호','인증일시','계정상태','권한'];
  const cell=v=>{const t=String(v??'');return /[",\n]/.test(t)?`"${t.replace(/"/g,'""')}"`:t};
  const body=rows.map(r=>[r.user_id,r.game_nickname,r.wago_nickname,r.wago_member_no,r.verified_at,r.user_status,r.user_role].map(cell).join(','));
  return '﻿'+[head.join(','),...body].join('\r\n');
}
function downloadWagoMigrationCsv(rows){
  const blob=new Blob([wagoMigrationCsv(rows)],{type:'text/csv;charset=utf-8'});
  const url=URL.createObjectURL(blob),a=document.createElement('a');
  const stamp=new Date().toISOString().slice(0,10);
  a.href=url;a.download=`와이고수-2차인증자-명단-${stamp}.csv`;document.body.appendChild(a);a.click();
  a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
