async function prisonUserAction(action){const userId=Number($('#selectedUserId')?.value||0),current=(state.users||[]).find(row=>Number(row.id)===userId),reason=String($('#prisonReason')?.value||'').trim(),durationMinutes=Number($('#prisonDuration')?.value||0);if(!userId)return alert('수감할 유저를 다시 선택하세요.');if(action==='PRISON'&&(!Number.isInteger(durationMinutes)||durationMinutes<10||durationMinutes>360))return alert('수감 시간은 10분부터 6시간까지 선택하세요.');if(!reason)return alert(action==='PRISON'?'수감 사유를 입력하세요.':'석방 사유를 입력하세요.');const message=action==='PRISON'?`${current?.nickname||'선택 유저'}를 ${durationMinutes}분 동안 감옥에 수감할까요?\nPVE·PVP·영토전 등 모든 콘텐츠가 즉시 차단됩니다.`:`${current?.nickname||'선택 유저'}를 즉시 석방할까요?`;if(!confirm(message))return;const button=action==='PRISON'?$('#prisonJailBtn'):$('#prisonReleaseBtn');if(button)button.disabled=true;try{await api('admin/users/action',{method:'POST',body:JSON.stringify({userId,action,reason,durationMinutes})});$('#userDialog').close();await loadUsers();alert(action==='PRISON'?`${durationMinutes}분 수감 명령을 전송했습니다.`:'석방 명령을 전송했습니다.')}catch(error){alert(error.message||'감옥 처리에 실패했습니다.');syncPrisonAdminPanel()}finally{if(button)button.disabled=false}}
function ensurePrisonAdminBlock(){const dialog=$('#userDialog');if(!dialog||$('#prisonAdminBlock'))return;const accountBlock=[...dialog.querySelectorAll('.actionBlock')].find(x=>x.querySelector('h3')?.textContent.includes('계정 관리'));if(!accountBlock)return;accountBlock.insertAdjacentHTML('beforebegin',`<div class="actionBlock prisonAdminBlock" id="prisonAdminBlock"><h3>행정부 감옥</h3><p class="muted">수감 즉시 PVE·PVP·영토전 등 모든 콘텐츠가 서버에서 차단되고 감옥 공개 채팅과 로그아웃만 허용됩니다.</p><div class="prisonAdminState" id="prisonAdminState"><b>현재 상태 확인 중</b></div><div class="two"><label class="field"><span>수감 시간 (분)</span><input id="prisonDuration" type="number" min="10" max="360" step="1" value="60"></label><label class="field"><span>처리 사유</span><input id="prisonReason" maxlength="200" value="운영 정책 위반" placeholder="수감 또는 석방 사유"></label></div><small class="muted">10분~360분(6시간) 사이에서 1분 단위로 설정합니다.</small><div class="two"><button type="button" id="prisonJailBtn" class="danger">감옥 수감</button><button type="button" id="prisonReleaseBtn">즉시 석방</button></div></div>`);$('#prisonJailBtn').onclick=()=>prisonUserAction('PRISON');$('#prisonReleaseBtn').onclick=()=>prisonUserAction('PRISON_RELEASE');if(!$('#prisonAdminStyle')){const style=document.createElement('style');style.id='prisonAdminStyle';style.textContent='.prisonAdminBlock{border-color:#6f3030!important;background:linear-gradient(145deg,rgba(83,24,24,.2),rgba(11,18,24,.94))!important}.prisonAdminState{display:grid;gap:4px;margin:10px 0 14px;padding:11px 13px;border:1px solid #34424b;background:#0b1218}.prisonAdminState b{font-size:13px}.prisonAdminState span{color:#94a3ac;font-size:12px}.prisonAdminState.is-active{border-color:#a94343;background:rgba(108,27,27,.25)}.prisonAdminState.is-active b{color:#ff8b82}';document.head.append(style)}}
