async function loadCoupons(){const d=await api('admin/coupons-v2'),restricted=state.admin?.restrictedPermissions===true;const rewardLabel=c=>({COIN:'코인',MASTER_STAR:'마스터의 별',PREMIUM_CUBE:'프리미엄 큐브',EQUIPMENT_SUPPLY_BOX:'장비 보급상자'}[String(c.reward_type||'COIN').toUpperCase()]||'보상');$('#coupons').innerHTML=`<div class="tr head"><b>쿠폰 코드</b><b>보상</b><b>사용량</b><b>유효기간</b><b class="optional">1인 제한</b><b>상태</b><b></b></div>`+(d.coupons.length?d.coupons.map(c=>`<div class="tr"><div class="couponCode"><b>${esc(c.code)}</b><button class="ghost copyCoupon" data-code="${esc(c.code)}">복사</button></div><span>${Number(c.reward_amount||c.reward_coin||0).toLocaleString()} ${rewardLabel(c)}</span><span>${c.used_count} / ${c.max_uses}</span><span>영구</span><span class="optional">계정당 1회</span><span><i class="statusPill ${c.is_active?'':'off'}">${c.is_active?'사용 가능':'중지됨'}</i></span>${restricted?'<span></span>':`<button data-coupon="${c.id}" data-active="${c.is_active}">${c.is_active?'비활성':'재활성'}</button>`}</div>`).join(''):'<div class="panel muted">발급된 쿠폰이 없습니다.</div>');document.querySelectorAll('[data-coupon]').forEach(b=>b.onclick=()=>toggleCoupon(b));document.querySelectorAll('.copyCoupon').forEach(b=>b.onclick=()=>copyCoupon(b.dataset.code,b))}
