function localDateTime(v){if(!v)return'';const raw=String(v).replace(' ','T');return raw.slice(0,16)}
function rankedKstLocalDateTime(v){if(!v)return'';const raw=String(v).trim(),date=new Date(/(?:z|[+-]\d{2}:?\d{2})$/i.test(raw)?raw:`${raw.replace(' ','T')}Z`);if(!Number.isFinite(date.getTime()))return localDateTime(v);const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(part=>[part.type,part.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`}
