async function mountHallOfFameCms(){if($('#hallOfFameCmsPanel'))return;const settingsView=$('#view-settings'),anchor=settingsView?.querySelector('.panel.formgrid');if(!settingsView||!anchor)return;anchor.insertAdjacentHTML('beforebegin',`<div class="panel" id="hallOfFameCmsPanel"><div class="maintenanceHead"><div><small>MAIN HALL OF FAME</small><h2>숲카라 명예의 전당</h2><p>메인 카드팩 화면에 표시되는 작은 명예 배너를 관리합니다.</p></div></div><div class="formgrid"><label class="field"><span>노출 상태</span><select id="hallOfFameEnabled"><option value="1">노출</option><option value="0">숨김</option></select></label><label class="field"><span>제목</span><input id="hallOfFameTitle" maxlength="40" value="숲카라 명예의 전당"></label><label class="field wide"><span>수상자 문구</span><input id="hallOfFameName" maxlength="80" value="🏆 남수단 🏆"></label></div><button type="button" id="saveHallOfFameBtn">명예의 전당 저장</button></div>`);const button=$('#saveHallOfFameBtn');button.disabled=state.role!=='OWNER';button.onclick=saveHallOfFameSettings;try{const d=await api('admin/settings'),x=d.settings||{};$('#hallOfFameEnabled').value=x.hall_of_fame_enabled??'1';$('#hallOfFameTitle').value=x.hall_of_fame_title||'숲카라 명예의 전당';$('#hallOfFameName').value=x.hall_of_fame_name||'🏆 남수단 🏆'}catch{}}
