function renderMonsterAdmin(){const rows=state.battleData?.monsters||[];$('#monsterAdminList').innerHTML=rows.map(m=>`<div class="panel monsterAdminRow" data-mid="${m.id}"><input class="mName" value="${esc(m.name)}"><input class="mImage" value="${esc(m.image||'')}" placeholder="이미지 경로"><input class="mPower" type="number" value="${m.battlePower}"><input class="mReward" type="number" value="${m.rewardCoin}"><select class="mBoss"><option value="0" ${m.isBoss?'':'selected'}>일반</option><option value="1" ${m.isBoss?'selected':''}>보스</option></select><select class="mActive"><option value="1" ${m.isActive?'selected':''}>사용</option><option value="0" ${m.isActive?'':'selected'}>중지</option></select><input class="mSort" type="number" value="${m.sortOrder||0}"><button class="saveMonster">저장</button><button class="ghost stopMonster">중지</button></div>`).join('');document.querySelectorAll('.saveMonster').forEach(b=>b.onclick=()=>saveMonster(b.closest('.monsterAdminRow')));document.querySelectorAll('.stopMonster').forEach(b=>b.onclick=()=>stopMonster(b.closest('.monsterAdminRow')))}
async function saveBattleAdminSettings(){const btn=$('#saveBattleSettingsBtn'),powerByGrade={},breakthroughBonus=[],gradeRates={};document.querySelectorAll('.battleGradeInput').forEach(x=>powerByGrade[String(x.dataset.grade||'').toUpperCase()]=Math.max(0,Math.floor(Number(x.value)||0)));document.querySelectorAll('.battleBtInput').forEach(x=>breakthroughBonus[Number(x.dataset.level)]=Number(x.value));const highBreakthroughBonus={};document.querySelectorAll('.battleHighBtInput').forEach(x=>{const grade=String(x.dataset.highGrade||'').toUpperCase();if(!highBreakthroughBonus[grade])highBreakthroughBonus[grade]=[];highBreakthroughBonus[grade][Number(x.dataset.highIndex)]=Number(x.value)});document.querySelectorAll('.battleDropGradeInput').forEach(x=>gradeRates[x.dataset.grade]=Number(x.value));const total=Object.values(gradeRates).reduce((a,b)=>a+Number(b||0),0);if(Math.abs(total-100)>0.001)return alert(`카드 드롭 등급 확률 합계를 100%로 맞춰주세요. 현재 ${total.toFixed(2)}%입니다.`);if(!Object.prototype.hasOwnProperty.call(powerByGrade,'PRESTIGE')||!Object.prototype.hasOwnProperty.call(powerByGrade,'ZENITH'))return alert('PRESTIGE/ZENITH 기본 전투력 입력값을 확인하세요.');const ultimateRules=state.battleData?.settings?.ultimateRules||[];setBusy(btn,true,'저장·검증 중...');try{const result=await api('admin/battle',{method:'PATCH',body:JSON.stringify({settings:{enabled:$('#battleEnabled').value==='1',engine:{mode:$('#battleEngineMode')?.value||'LEGACY',playbackSpeed:1.6},powerByGrade,breakthroughBonus,highBreakthroughBonus,cardDrop:{enabled:$('#battleCardDropEnabled').value==='1',defaultRate:Number($('#battleCardDropDefaultRate').value),gradeRates},energy:state.battleData?.settings?.energy,ultimateRules}})}),saved=result?.settings?.powerByGrade||{};if(Number(saved.PRESTIGE)!==Number(powerByGrade.PRESTIGE))throw Error(`PRESTIGE 전투력 저장 검증 실패 (요청 ${Number(powerByGrade.PRESTIGE).toLocaleString()} / 서버 ${Number(saved.PRESTIGE||0).toLocaleString()})`);if(Number(saved.ZENITH)!==Number(powerByGrade.ZENITH))throw Error(`ZENITH 전투력 저장 검증 실패 (요청 ${Number(powerByGrade.ZENITH).toLocaleString()} / 서버 ${Number(saved.ZENITH||0).toLocaleString()})`);alert(`전투 설정이 저장되었습니다.\n엔진 ${String(result?.settings?.engine?.mode||'LEGACY')} · V2 속도 1.6배 고정\nPRESTIGE ${Number(saved.PRESTIGE).toLocaleString()} · ZENITH ${Number(saved.ZENITH).toLocaleString()} 적용 확인`);await loadBattleAdmin()}finally{setBusy(btn,false)}}

async function saveUltimateSettings(){const btn=$('#saveUltimateSettingsBtn');const ultimateRules=collectUltimateRules();for(const [i,u] of ultimateRules.entries()){if(!Number.isFinite(u.activationChance)||u.activationChance<0||u.activationChance>100)return alert(`궁극기 조건 ${i+1}의 발동 확률을 0~100으로 입력하세요.`);if(!Number.isFinite(u.coefficientPercent)||u.coefficientPercent<0||u.coefficientPercent>100000)return alert(`궁극기 조건 ${i+1}의 계수를 0~100000으로 입력하세요.`);if(!u.mediaUrl)u.mediaUrl='/assets/effects/SKILL.gif';if(!u.mediaUrl.startsWith('/')&&!/^https?:\/\//i.test(u.mediaUrl))u.mediaUrl='/'+u.mediaUrl.replace(/^\/+/, '');}setBusy(btn,true,'저장·검증 중...');try{const saved=await api('admin/battle',{method:'PATCH',body:JSON.stringify({ultimateRules})});const verified=await api('admin/battle');const actual=verified.settings?.ultimateRules||[];if(JSON.stringify(actual)!==JSON.stringify(saved.ultimateRules||ultimateRules))throw Error('D1 저장 후 재조회 값이 일치하지 않습니다.');state.battleData=verified;renderUltimateRules(actual);alert('궁극기 설정이 D1에 저장되었고 재조회 검증까지 완료되었습니다.')}finally{setBusy(btn,false)}}
