let tierSaveInFlight=false;
async function patchTierSettings(payload,message){
  if(tierSaveInFlight)return alert('티어 설정을 저장 중입니다. 잠시만 기다려주세요.');
  tierSaveInFlight=true;
  const body=JSON.stringify(payload);
  try{
    let saved;
    try{
      saved=await api('admin/tiers',{method:'PATCH',body});
    }catch(e){
      if(Number(e?.status)!==404)throw e;
      saved=await api('admin/tiers',{method:'POST',body});
    }
    if(saved?.settings){
      state.tierData={...(state.tierData||{}),settings:saved.settings};
      const p=saved.settings.pvp||{};
      $('#pvpEnabled').value=p.enabled===false?'0':'1';
      $('#pvpTierStatus').value=p.status||'진행 중';
      $('#pvpSeasonEnglishTitle').value=p.seasonTitle||'SOOPKETMON RANKED';
      $('#pvpSeasonName').value=p.seasonName||'시즌 1';
      $('#pvpSeasonDescription').value=p.seasonDescription||'티어와 편성 전투력을 기준으로 상대가 자동 배정되는 랭크전입니다.';
      $('#pvpSeasonStart').value=rankedKstLocalDateTime(p.startsAt);
      $('#pvpSeasonEnd').value=rankedKstLocalDateTime(p.endsAt);
      renderTierAdmin();
    }
    alert(message);
  }finally{
    tierSaveInFlight=false;
  }
}
async function saveCardTierAdmin(){await patchTierSettings({cardScoreTiers:collectCardScoreTiers()},'카드점수 티어 구간이 저장되었습니다.')}
async function savePvpSeasonSettings(){const pvp={enabled:$('#pvpEnabled').value==='1',automaticSeasons:$('#pvpAutomaticSeasons')?.value!=='0',seasonDurationDays:Number($('#pvpSeasonDurationDays')?.value||5),matchingMode:'AUTO',competitionName:'랭크전',status:$('#pvpTierStatus').value.trim(),seasonTitle:$('#pvpSeasonEnglishTitle').value.trim(),seasonName:$('#pvpSeasonName').value.trim(),seasonDescription:$('#pvpSeasonDescription').value.trim(),startsAt:rankedKstToUtcSql($('#pvpSeasonStart').value),endsAt:rankedKstToUtcSql($('#pvpSeasonEnd').value),rewardClaimMode:$('#pvpRewardClaimMode').value,tierRewardsEnabled:$('#pvpTierRewardsEnabled').value==='1',rankRewardsEnabled:$('#pvpRankRewardsEnabled').value==='1'};if(pvp.startsAt&&pvp.endsAt&&Date.parse(`${pvp.endsAt.replace(' ','T')}Z`)<=Date.parse(`${pvp.startsAt.replace(' ','T')}Z`))return alert('시즌 종료일은 시작일보다 뒤여야 합니다.');await patchTierSettings({pvp},'랭크전 5일 자동 시즌 설정이 저장되었습니다.')}
async function savePvpPolicySettings(){const pvp={initialScore:Number($('#pvpInitialScore').value),winScore:Number($('#pvpWinScore').value),loseScore:Number($('#pvpLoseScore').value),winCoin:Number($('#pvpWinCoin')?.value??50),loseCoin:Number($('#pvpLoseCoin')?.value??25),scoreBalance:{enabled:$('#pvpScoreBalanceEnabled').value==='1',equalRange:Number($('#pvpScoreEqualRange').value),weakerWinMid:Number($('#pvpWeakerWinMid').value),weakerWinHigh:Number($('#pvpWeakerWinHigh').value),weakerWinExtreme:Number($('#pvpWeakerWinExtreme').value),strongerWinMid:Number($('#pvpStrongerWinMid').value),strongerWinHigh:Number($('#pvpStrongerWinHigh').value),strongerWinExtreme:Number($('#pvpStrongerWinExtreme').value),strongerLossMid:Number($('#pvpStrongerLossMid').value),strongerLossHigh:Number($('#pvpStrongerLossHigh').value),strongerLossExtreme:Number($('#pvpStrongerLossExtreme').value),weakerLossMid:Number($('#pvpWeakerLossMid').value),weakerLossHigh:Number($('#pvpWeakerLossHigh').value),weakerLossExtreme:Number($('#pvpWeakerLossExtreme').value),minChange:Number($('#pvpMinScoreChange').value),maxChange:Number($('#pvpMaxScoreChange').value)},matchCardRange:Number($('#pvpMatchCardRange').value),matchSeasonRange:Number($('#pvpMatchSeasonRange').value),historyLimit:Number($('#pvpHistoryLimit').value),energy:{...(state.tierData?.settings?.pvp?.energy||{}),enabled:$('#pvpEnergyEnabled').value==='1',maxEnergy:Number($('#pvpEnergyMax').value),rechargeMinutes:Number($('#pvpEnergyMinutes').value),costPerBattle:1,adminUnlimited:$('#pvpAdminUnlimited').value==='1',testUnlimited:$('#pvpTestUnlimited').value==='1'}};await patchTierSettings({pvp},'랭크전 자동 매칭·점수 정책이 저장되었습니다.')}
