async function loadMineralAdmin(){const d=await api('admin/mineral-exchange');const s=d.settings||{};const a=$('#mineralBaseAmount'),b=$('#mineralPayoutCoin'),c=$('#mineralDailyLimitCoin'),e=$('#mineralExchangeEnabled');if(a)a.value=Number(s.baseMineral||100000000);if(b)b.value=Number(s.payoutCoin||1000);if(c)c.value=Number(s.dailyLimitCoin||3000);if(e)e.value=s.enabled===false?'0':'1';renderMineralAdminRequests(d.requests||[])}
function renderMineralAdminRequests(rows){const box=$('#mineralAdminList');if(!box)return;const labels={PENDING:'승인 대기',APPROVED:'승인 완료',REJECTED:'거절'};box.innerHTML=rows.length?rows.map(r=>`<article class="mineralAdminRow status-${String(r.status).toLowerCase()}" data-id="${r.id}"><div class="mineralAdminMain"><b>${esc(r.game_nickname)} <small>(${esc(r.wago_nickname)})</small></b><span>미네랄 ${Number(r.mineral_amount).toLocaleString()}개 → <strong>${Number(r.coin_amount).toLocaleString()}코인</strong></span><p>${esc(r.proof_text)}</p><small>신청 ${fmt(r.created_at)} · 기준일 ${esc(r.requested_kst_date)}</small></div><em>${labels[r.status]||esc(r.status)}</em>${r.status==='PENDING'?`<div class="mineralAdminActions"><button type="button" data-mineral-action="APPROVE">승인</button><button type="button" data-mineral-action="REJECT" class="danger">거절</button></div>`:`<div class="mineralReviewInfo">${r.reviewer_name?`처리: ${esc(r.reviewer_name)} · ${fmt(r.reviewed_at)}`:''}${r.reject_reason?`<br>사유: ${esc(r.reject_reason)}`:''}</div>`}</article>`).join(''):'<div class="muted">미네랄 교환 신청 내역이 없습니다.</div>';box.querySelectorAll('[data-mineral-action]').forEach(btn=>btn.onclick=()=>reviewMineralRequest(btn.closest('.mineralAdminRow'),btn.dataset.mineralAction));}
async function saveMineralSettings(){const settings={enabled:$('#mineralExchangeEnabled').value==='1',baseMineral:Number($('#mineralBaseAmount').value),payoutCoin:Number($('#mineralPayoutCoin').value),dailyLimitCoin:Number($('#mineralDailyLimitCoin').value)};if(settings.dailyLimitCoin%1000!==0)return alert('하루 최대 교환 코인은 1,000코인 단위로 입력하세요.');await api('admin/mineral-exchange',{method:'PATCH',body:JSON.stringify({settings})});alert('미네랄 교환 설정이 저장되었습니다.');await loadMineralAdmin()}
async function reviewMineralRequest(row,action){const id=Number(row.dataset.id);if(action==='APPROVE'){if(!confirm('기부 내역을 확인했습니까? 승인하면 즉시 코인이 지급됩니다.'))return;await api('admin/mineral-exchange',{method:'PATCH',body:JSON.stringify({id,action})});alert('승인 및 코인 지급이 완료되었습니다.')}else{const reason=prompt('거절 사유를 입력하세요.','기부 내역 확인 불가');if(reason===null)return;await api('admin/mineral-exchange',{method:'PATCH',body:JSON.stringify({id,action,reason})});alert('교환 신청을 거절했습니다.')}await loadMineralAdmin()}


async function loadPvpSettlementPreview(){const box=$('#pvpSettlementPreview'),status=$('#pvpSettlementStatus');if(box)box.innerHTML='<div class="muted">정산 정보를 확인 중입니다.</div>';const d=await api('admin/pvp-settlement');if(status)status.innerHTML=[['대상 유저',Number(d.summary?.participants||0).toLocaleString()],['보상 대상',Number(d.summary?.rewardUsers||0).toLocaleString()],['총 코인',Number(d.summary?.rewardCoin||0).toLocaleString()],['총 카드조각',Number(d.summary?.rewardShards||0).toLocaleString()],['정산 상태',esc(d.existing?.status||'미정산')]].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('');if(box)box.innerHTML=(d.preview||[]).slice(0,30).map(r=>`<div class="tr"><span>${r.final_rank}위</span><b>${esc(r.nickname)}</b><span>${Number(r.season_score).toLocaleString()}점 · ${esc(r.tier?.name||'-')}</span><span>코인 ${Number(r.rewardCoin||0).toLocaleString()} · 조각 ${Number(r.rewardShards||0).toLocaleString()}</span></div>`).join('')||'<div class="muted">정산 대상이 없습니다.</div>';return d}
async function executePvpSettlement(){if($('#pvpEnabled').value!=='0')return alert('먼저 랭크전 사용 여부를 OFF로 저장하세요.');const season=$('#pvpSeasonName').value.trim();const typed=prompt(`정산은 되돌릴 수 없습니다.\n현재 시즌명 [${season}] 을 정확히 입력하세요.`);if(typed===null)return;if(typed.trim()!==season)return alert('시즌명이 일치하지 않아 취소했습니다.');if(!confirm('최종 순위 스냅샷과 보상 메시지를 생성한 뒤 랭크전 시즌 기록을 초기화합니다. 계속할까요?'))return;const btn=$('#executePvpSettlementBtn');btn.disabled=true;try{let d=null,loops=0;do{loops++;btn.textContent=d?.phase==='MESSAGES'?`보상 메시지 생성 중... ${Number(d.processed||0).toLocaleString()}`:d?.phase==='SNAPSHOT'?`순위 저장 중... ${Number(d.processed||0).toLocaleString()} / ${Number(d.total||0).toLocaleString()}`:'정산 준비 중...';d=await api('admin/pvp-settlement',{method:'POST',timeoutMs:20000,body:JSON.stringify({confirmSeasonName:season})});if(!d.done)await new Promise(r=>setTimeout(r,250));if(loops>500)throw Error('정산 반복 한도를 초과했습니다. 다시 실행하면 이어서 처리됩니다.')}while(!d.done);alert(`정산 완료\n대상 ${d.participants}명\n보상 메시지 ${d.messages}개\n초기화 ${d.resetProfiles}명`);await loadTierAdmin();await loadPvpSettlementPreview()}finally{btn.disabled=false;btn.textContent='긴급 정산 실행'}}
